'use strict';
const RAID_SAVE_KEY='grand-journey-raid-v39';
function raidNames(){G.BY[JourneyRaid.TREE].name=L('Corrupted Ancient Tree','Árvore ancestral corrompida');G.BY[JourneyRaid.SPROUT].name=L('Carnivorous Sprout','Broto carnívoro');}
for(const id of Object.values(JourneyRaid.SPECS).flatMap(d=>[d.boss,d.minion])){const im=new Image();im.src=CA[id].sprite;IM[id]=im;for(const pose of ['idle','walk','attack'])IM[id+':'+pose]=im;}
function raidHud(){if(!S?.raid)return '';raidNames();const r=S.raid,boss=battle?.raid?battle.units.find(u=>u.raidBoss):null,hp=boss?JourneyRaid.health(battle):r.hp;return '<section class="raid-hud"><div><b>'+G.BY[S.raid.bossType||JourneyRaid.TREE].name+'</b><span class="raid-hp-text">'+Math.ceil(hp).toLocaleString(I18n.lang==='pt-BR'?'pt-BR':'en-US')+' / '+r.maxHp.toLocaleString(I18n.lang==='pt-BR'?'pt-BR':'en-US')+'</span></div><progress max="'+r.maxHp+'" value="'+hp+'" aria-label="'+L('Boss health','Vida do chefe')+'"></progress></section>';}
const raidArenaStatus=arenaStatus;arenaStatus=function(combat=false){if(!S?.raid)return raidArenaStatus(combat);const status=raidArenaStatus(combat);return status+raidHud();};
const raidPrep=prep;prep=function(){raidPrep();if(!S?.raid)return;document.querySelector('.hidden-enemy')?.remove();const overlay=document.createElement('div');overlay.className='raid-preview';overlay.innerHTML=JourneyRaid.formation(S).map(unit=>{const a=CA[unit.type],p=GPosition(unit.pos,1),height=a.size[1]*a.scale*(88/112),w=height*a.size[0]/a.size[1],top=(unit.uid==='raid-tree'?180:p.y)-height+10*(88/112);return '<img src="'+a.sprite+'" alt="'+esc(G.BY[unit.type].name)+'" style="left:'+((p.x-w/2)/430*100)+'%;top:'+(top/540*100)+'%;width:'+(w/430*100)+'%;height:'+(height/540*100)+'%">';}).join('');document.querySelector('.arena-stage .field').append(overlay);save();};
const raidConfig=trainingConfig;trainingConfig=function(){raidConfig();const node=document.createElement('section');node.className='raid-entry';node.innerHTML='<h3>'+L('Raid — Ancient Tree','Raid — Árvore ancestral')+'</h3><p>'+L('Uses your configured team, upgrades and relics. Enemy settings are ignored. Five rounds maximum, without a time limit. Defeat the Tree before it wins five rounds. No rewards.','Usa sua equipe, melhorias e relíquias configuradas. Ignora as configurações do inimigo. Até cinco rodadas, sem limite de tempo. Derrote a Árvore antes de ela vencer cinco rodadas. Sem recompensas.')+'</p>'+metaButton('raid-start',L('Start new raid','Iniciar nova raid'),'','primary')+(raidHasSave()?metaButton('raid-resume',L('Resume saved raid','Retomar raid salva')):'');document.querySelector('.training-config').append(node);const actions=document.createElement('div');actions.className='training-sticky stack';document.querySelectorAll('[data-act="training-start"],[data-act="raid-start"],[data-act="raid-resume"]').forEach(button=>actions.append(button));document.querySelector('.training-config').append(actions);mountScreenFooter();};
function raidHasSave(){try{return !!localStorage.getItem(RAID_SAVE_KEY);}catch{return false;}}
function raidStart(){trainingLoad();const config=JSON.parse(JSON.stringify(trainingDraft));config.enemy=Training.side();const error=Training.validate(config,Progress.playerUnits().map(u=>u.id));if(error){toast(L('Check your team: 20 cards, up to 4 copies, relics fitting the bag.','Confira sua equipe: 20 cartas, até 4 cópias e relíquias que caibam na bolsa.'));return;}trainingStop();closeModal();trainingStore();trainingReturnRun=S;S=JourneyRaid.build(config,Date.now()>>>0,Progress.playerUnits().map(u=>u.id));battle=null;selected=null;raidNames();render();save();}
let raidStorageWarning=false,raidSavedAt=0;
function raidCheckpoint(){if(!S?.raid)return;if(S.raid.run){raidSave();raidSavedAt=performance.now();return;}try{localStorage.setItem(RAID_SAVE_KEY,JourneyRaid.snapshot(S,battle));raidSavedAt=performance.now();raidStorageWarning=false;}catch{if(!raidStorageWarning){raidStorageWarning=true;toast(L('Raid could not be saved on this device.','Não foi possível salvar a raid neste dispositivo.'));}}}
const raidSave=save;save=function(){if(!S?.raid?.run)raidCheckpoint();return raidSave();};
const raidStop=trainingStop;trainingStop=function(){raidCheckpoint();raidStop();};
window.addEventListener('pagehide',raidCheckpoint);document.addEventListener('visibilitychange',()=>{if(document.hidden)raidCheckpoint();});
function raidResume(){let data;try{data=JourneyRaid.restore(localStorage.getItem(RAID_SAVE_KEY));}catch{toast(L('This raid save could not be restored.','Não foi possível retomar este save da raid.'));return;}trainingStop();closeModal();trainingReturnRun=S;S=data.state;battle=data.battle;selected=null;raidNames();if(S.phase==='battle')startBattle(battle);else render();}
const raidGuard=JourneyTraining.guard;JourneyTraining.guard=function(e){const a=e.target.closest?.('[data-act]')?.dataset.act;if(e.type==='click'&&['raid-start','raid-resume','raid-repeat'].includes(a)){e.preventDefault();e.stopImmediatePropagation();if(a==='raid-repeat'){trainingDraft=JSON.parse(JSON.stringify(S.training));raidStart();}else if(a==='raid-start')raidStart();else raidResume();return true;}if(S?.raid&&a==='enemy-relics'){e.preventDefault();e.stopImmediatePropagation();openModal('<h2>'+L('Raid opponent','Inimigo da raid')+'</h2><p>'+L('The monster uses its own mechanics, without a deck, purchases or relics.','O monstro usa suas próprias mecânicas, sem deck, compras ou relíquias.')+'</p>'+raidHud()+metaButton('close',L('Back','Voltar')));return true;}return raidGuard(e);};
const raidPaint=paintCombat;paintCombat=function(now){raidPaint(now);if(!battle?.raid)return;const c=$('combat').getContext('2d'),r=battle.raid;c.save();for(const m of r.roots){c.strokeStyle='#f5a0ff';c.fillStyle='#ab41b84a';c.lineWidth=3;c.setLineDash([5,4]);c.beginPath();c.arc(m.x,m.y,r.config.rootRadius,0,Math.PI*2);c.fill();c.stroke();c.setLineDash([]);c.fillStyle='#fff';c.font='18px VT323';c.textAlign='center';c.fillText('!',m.x,m.y+5);}const boss=battle.units.find(u=>u.raidBoss);if(r.channel){for(const u of battle.units.filter(u=>u.hp>0&&r.channel.contributors.includes(u.uid))){c.strokeStyle='#b7f77b';c.lineWidth=3;c.beginPath();c.moveTo(u.x,u.y-15);c.lineTo(boss.x,boss.y-40);c.stroke();}c.fillStyle='#daffc2';c.font='18px VT323';c.textAlign='center';c.fillText(L('CHANNELING','CANALIZANDO'),boss.x,boss.y+35);}c.restore();const hud=document.querySelector('.arena-shell > .raid-hud');if(hud){const hp=Math.ceil(JourneyRaid.health(battle)),bar=hud.querySelector('progress'),text=hud.querySelector('.raid-hp-text');if(bar)bar.value=JourneyRaid.health(battle);if(text&&text.dataset.hp!==String(hp)){text.textContent=hp.toLocaleString(I18n.lang==='pt-BR'?'pt-BR':'en-US')+' / '+S.raid.maxHp.toLocaleString(I18n.lang==='pt-BR'?'pt-BR':'en-US');text.dataset.hp=String(hp);}}if(performance.now()-raidSavedAt>=500)raidCheckpoint();};
const raidResult=resultView;resultView=function(){if(!S?.raid||S.raid.run&&S.phase!=='roundResult')return raidResult();const next=S.phase==='roundResult';show('<section class="training-result"><div class="eyebrow">'+(S.raid.run?L('RAID','RAID'):L('TRAINING RAID · NO REWARDS','RAID DE TREINO · SEM RECOMPENSAS'))+'</div><h2>'+L(next?'The monster survives':S.phase==='victory'?'Monster defeated!':'Raid defeated',next?'O monstro resistiu':S.phase==='victory'?'Monstro derrotado!':'Derrota na raid')+'</h2>'+raidHud()+'<div class="stack">'+(next?metaButton('next-round',L('Prepare round ','Preparar rodada ')+(S.round+1),'','primary'):metaButton('raid-repeat',L('New raid · same team','Nova raid · mesma equipe'),'','primary'))+(S.raid.run?'':metaButton('training-config',L('Training settings','Configurações do treino'))+metaButton('training-home',L('Main menu','Menu principal')))+'</div>'+damageReport()+'</section>');};

const raidAttackPaint=paintCombat;paintCombat=function(now){raidAttackPaint(now);if(!battle?.raid)return;const c=$('combat').getContext('2d'),boss=battle.units.find(u=>u.raidBoss),time=battle.time;c.save();
for(const a of battle.raid.attacks||[]){const target=battle.units.find(u=>u.uid===a.target);if(!target||target.hp<=0)continue;const x=boss.x,y=boss.y-74;if(time<a.launch){const k=Math.min(1,(time-a.start)/a.windup);c.fillStyle=JourneyRaid.spec(battle.raid).color;c.strokeStyle='#f4d3ff';c.lineWidth=2;c.beginPath();c.arc(x,y,7+8*k,0,Math.PI*2);c.fill();c.stroke();c.strokeStyle='#b875e080';c.beginPath();c.moveTo(x,y);c.lineTo(target.x,target.y-22);c.stroke();}else{const k=Math.min(1,(time-a.launch)/a.travel),tx=target.x,ty=target.y-22,px=x+(tx-x)*k,py=y+(ty-y)*k;c.strokeStyle=JourneyRaid.spec(battle.raid).color;c.lineWidth=6;c.beginPath();c.moveTo(px-(tx-x)*.14,py-(ty-y)*.14);c.lineTo(px,py);c.stroke();c.fillStyle='#fff0bc';c.beginPath();c.arc(px,py,7,0,Math.PI*2);c.fill();}}
for(const e of battle.effects.filter(e=>e.kind==='raid-impact')){const k=1-e.life/e.full;c.strokeStyle=JourneyRaid.spec(battle.raid).color;c.lineWidth=4*(1-k)+1;c.globalAlpha=1-k;c.beginPath();c.arc(e.x,e.y,8+26*k,0,Math.PI*2);c.stroke();c.fillStyle='#fff0c9';c.fillRect(e.x-3,e.y-12,6,24);c.fillRect(e.x-12,e.y-3,24,6);}c.restore();};
